private async sendOrganizationInvitation(params: {
  appUser: CurrentUserDto;
  organization: Pick<OrganizationEntity, "id" | "name">;
  email: string;
  token: string;
  expiresAt: Date;
}): Promise<void> {
  await this.customerio.sendOrganizationInvitation({
    email: params.email,
    organizationName: params.organization.name,
    inviteUrl: this.organizationInvitationUrl(params.token),
    invitedByEmail: params.appUser.email,
    invitedByName: params.appUser.name,
    expiresAt: params.expiresAt,
  });
  this.customerio.track(
    params.appUser.id,
    CustomerioEvent.OrganizationInvitationSent,
    {
      organization_id: params.organization.id,
      invited_email: params.email,
    },
  );
}

