useEffect(() => {
  if (hasSubmittedRef.current) return;
  hasSubmittedRef.current = true;

  const token = searchParams.get("token")?.trim();
  if (!token) {
    setState("error");
    setMessage("This invitation link is missing a token.");
    return;
  }

  const redirectToLogin = async () => {
    const authMode =
      await usersApiService.getOrganizationInvitationAuthMode(token);
    persistPostAuthRedirect(
      `${window.location.pathname}${window.location.search}`,
    );
    navigate(
      authMode === "signup"
        ? "/login?resume=organization-invitation&intent=signup"
        : "/login?resume=organization-invitation",
      { replace: true },
    );
  };

  const acceptInvitation = async () => {
    try {
      const session = await fetchAuthSession();
      if (!session.tokens?.idToken) {
        await redirectToLogin();
        return;
      }

      const organization =
        await usersApiService.acceptOrganizationInvitation(token);
      consumePostAuthRedirect();
      await fetchAuthSession({ forceRefresh: true });
      await loadUser();
      setState("success");
      setMessage(`You've joined ${organization.name}.`);
    } catch (error) {
      if (
        error instanceof Error &&
        error.name === "UserUnAuthenticatedException"
      ) {
        await redirectToLogin();
        return;
      }
      setState("error");
      setMessage(
        error instanceof Error
          ? error.message
          : "Failed to accept invitation.",
      );
      captureClientError("organization_invitation.accept_failed", error, {
        endpoint: "/api/users/organization/invitations/accept",
      });
    }
  };

  void acceptInvitation();
}, [loadUser, navigate, searchParams]);

